<?php
$id=$args['section'];$data=rzz_about_sections()[$id];$prefix='about_'.$id.'_';
?><section class="about-principles about-<?php echo esc_attr($id); ?> section <?php echo $id==='practice'?'pattern':'light'; ?>" aria-labelledby="<?php echo esc_attr($id); ?>-heading"><div class="container"><header class="principles-heading"><p class="eyebrow"><?php rzz_text($prefix.'label',$data['label']); ?></p><h2 id="<?php echo esc_attr($id); ?>-heading"><?php rzz_text($prefix.'title',$data['title']); ?></h2></header><ol class="principles-grid"><?php foreach($data['items'] as $i=>$item): ?><li class="principle-card"><span class="principle-marker" aria-hidden="true"><?php if($id==='guides'): ?><span class="brand-dots"><i></i><i></i><i></i></span><?php else:echo esc_html($id==='practice'?['I','II','III'][$i]:(string)($i+1));endif; ?></span><h3><?php rzz_text($prefix.$i.'_title',$item[0]); ?></h3><p><?php rzz_text($prefix.$i.'_text',$item[1]); ?></p></li><?php endforeach; ?></ol></div></section>